def find_same_regions(grid, min_height=2):
    """Find rectangular regions that appear identically in consecutive rows"""
    h, w = len(grid), len(grid[0])

    # For each position, track how far right the non-zero run goes
    def get_run_length(r, c):
        length = 0
        while c + length < w and grid[r][c + length] != 0:
            length += 1
        return length

    # Find common start/end pairs between consecutive rows
    matches = []
    for r in range(h - min_height + 1):
        row_pattern = {}
        for c in range(w):
            if grid[r][c] != 0:
                l = get_run_length(r, c)
                key = (c, l)
                if key not in row_pattern:
                    row_pattern[key] = {'first_r': r, 'first_c': c, 'first_l': l}

        # Check next row for overlap
        for c in range(w):
            if grid[r+1][c] != 0:
                l_next = get_run_length(r+1, c)
                # Check if there's a matching run in row r
                for kc, kl in [(c-k-l+1, k+l) for k in range(min(5, max(l, l_next)))] if False else []:
                    pass

        # Simpler: find exact match of a subsegment
        for c_start in range(w):
            for c_end in range(c_start + 1, w):
                segment_len = c_end - c_start
                if segment_len <= 2:  # Match only small segments
                    seg = tuple(test_in[r][c_start:c_end])
                    for r_check in range(r+1, min(r+min_height+1, h)):
                        match_row = grid[r_check]
                        match_seg = match_row[c_start:c_end]
                        if seg == match_seg:
                            print(f"\nMatch found:")
                            print(f"Rows {r}-{r_check}, cols {c_start}-{c_end}")
                            print(f"Segment: {seg}")
                            for rr in range(r, r_check+1):
                                print(f"  Row {rr}[{c_start}:{c_end}] = {match_row[c_start:c_end]}")

