def find_isolated_rectangles(grid):
    """Find rectangular regions that are surrounded by zeros on all sides"""
    h, w = len(grid), len(grid[0])

    # For each cell with non-zero, find max rectangle it belongs to
    def expand_rect(r, c):
        # Go up
        r_start = r
        while r_start > 0 and grid[r_start-1][c] != 0:
            r_start -= 1
        # Go down  
        r_end = r + 1
        while r_end < h and grid[r_end][c] != 0:
            r_end += 1
        r_range = range(r_start, r_end)

        # Go left within each row
        for rr in r_range:
            c_left = c
            while c_left > 0 and grid[rr][c_left-1] != 0:
                c_left -= 1
            # Go right within each row
            c_right = c + 1
            while c_right < w and grid[rr][c_right] != 0:
                c_right += 1
            if c_right <= c_left:
                break

        return r_range, list(range(c_left, c_right))

    found = set()
    results = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in found:
                r_range, c_range = expand_rect(r, c)

                # Check if truly isolated (zero neighbors in all directions)
                isolated = True

                # Check top neighbor (all cols in rect)
                if r > 0:
                    for cc in c_range:
                        if grid[r-1][cc] != 0:
                            isolated = False
                            break

                if not isolated:
                    continue

                # Check bottom neighbor (all cols in rect)
                if r_end < h:
                    for cc in c_range:
                        if grid[r_end][cc] != 0:
                            isolated = False
                            break

                if not isolated:
                    continue

                # Check left neighbor (all rows in rect)
                if c_left > 0:
                    for rr in r_range:
                        if grid[rr][c_left-1] != 0:
                            isolated = False
                            break

                if not isolated:
                    continue

                # Check right neighbor (all rows in rect)
                if c_right < w:
                    for rr in r_range:
                        if grid[rr][c_right] != 0:
                            isolated = False
                            break

                if isolated:
                    cells = set((rr, cc) for rr in r_range for cc in c_range)
                    results.append(cells)
                    for cell in cells:
                        found.add(cell)

    return results

