                while c_left > 0 and grid[r][c_left-1] != 0:
                    c_left -= 1
                while c_right < w - 1 and grid[r][c_right+1] != 0:
                    c_right += 1

                # Expand vertically
                r_top, r_bottom = r, r
                while r_top > 0 and all(grid[r_top-1][cc] != 0 for cc in range(c_left, c_right+1)):
                    r_top -= 1
                while r_bottom < h - 1 and all(grid[r_bottom+1][cc] != 0 for cc in range(c_left, c_right+1)):
                    r_bottom += 1

                # Check isolation
                isolated = True
                if r_top > 0 and any(grid[r_top-1][cc] != 0 for cc in range(c_left, c_right+1)):
                    isolated = False
                if r_bottom < h - 1 and any(grid[r_bottom+1][cc] != 0 for cc in range(c_left, c_right+1)):
                    isolated = False
                if c_left > 0 and any(grid[rr][c_left-1] != 0 for rr in range(r_top, r_bottom+1)):
